  `batchname` varchar(100) NOT NULL,
  `orientationdate` date DEFAULT NULL,
  `subject` varchar(45) NOT NULL DEFAULT 'ML',
  `startdate` date DEFAULT NULL,
  `enddate` date DEFAULT NULL,
  `lastmoddatetime` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `batchid` int NOT NULL AUTO_INCREMENT,
  `courseid` int DEFAULT NULL,
  PRIMARY KEY (`batchid`),
  KEY `fk_course_idx` (`courseid`)
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb3 COMMENT='Batch Table';
