/*!50003 CREATE*/ /*!50017 DEFINER=`whitebox-db`@`%`*/ /*!50003 TRIGGER `trg_candidate_status_sync` AFTER UPDATE ON `candidate` FOR EACH ROW BEGIN
    /* =====================================================
       CASE 1: Candidate becomes INACTIVE / BREAK / CLOSED
       ===================================================== */
    IF OLD.status <> NEW.status
       AND NEW.status IN ('inactive','break','closed','discontinued') THEN

        UPDATE candidate_preparation
        SET status = 'inactive'
        WHERE candidate_id = NEW.id
          AND status = 'active';

        UPDATE candidate_marketing
        SET status = 'inactive'
        WHERE candidate_id = NEW.id
          AND status = 'active';

    END IF;

    /* =====================================================
       CASE 2: Candidate becomes ACTIVE (CLONE LAST RECORD)
       ===================================================== */
    IF OLD.status <> NEW.status
       AND NEW.status = 'active' THEN

        /* ---------- Clone Preparation ---------- */
        IF EXISTS (
            SELECT 1
            FROM candidate_preparation
            WHERE candidate_id = NEW.id
        ) THEN
            INSERT INTO candidate_preparation (
                candidate_id,
                start_date,
                status,
                instructor1_id,
                instructor2_id,
                instructor3_id,
                rating,
                communication,
                years_of_experience,
                target_date,
                notes,
                linkedin_id,
                github_url,
                resume_url,
                move_to_mrkt
            )
            SELECT
                candidate_id,
                CURDATE(),            -- reset lifecycle date
                'active',
                instructor1_id,
                instructor2_id,
                instructor3_id,
                rating,
                communication,
                years_of_experience,
                target_date,
                notes,
                linkedin_id,
                github_url,
                resume_url,
                move_to_mrkt
            FROM candidate_preparation
            WHERE candidate_id = NEW.id
              AND status = 'inactive'
            ORDER BY id DESC
            LIMIT 1;
        END IF;

        /* ---------- Clone Marketing ---------- */
        IF EXISTS (
            SELECT 1
            FROM candidate_marketing
            WHERE candidate_id = NEW.id
        ) THEN
            INSERT INTO candidate_marketing (
                candidate_id,
                start_date,
                status,
                marketing_manager,
                email,
                password,
                imap_password,
                google_voice_number,
                linkedin_username,
                linkedin_passwd,
                priority,
                notes,
                move_to_placement,
                resume_url,
                linkedin_premium_end_date
            )
            SELECT
                candidate_id,
                CURDATE(),            -- reset lifecycle date
                'active',
                marketing_manager,
                email,
                password,
                imap_password,
                google_voice_number,
                linkedin_username,
                linkedin_passwd,
                priority,
                notes,
                move_to_placement,
                resume_url,
                linkedin_premium_end_date
            FROM candidate_marketing
            WHERE candidate_id = NEW.id
              AND status = 'inactive'
            ORDER BY id DESC
            LIMIT 1;
        END IF;

    END IF;

END */;;
DELIMITER ;
