/*!50003 CREATE*/ /*!50017 DEFINER=`whitebox-db`@`%`*/ /*!50003 TRIGGER `trg_candidate_placement_after_update` AFTER UPDATE ON `candidate_placement` FOR EACH ROW BEGIN
  DECLARE old_n INT DEFAULT 0;
  DECLARE new_n INT DEFAULT 0;
  DECLARE i INT DEFAULT 1;

  DECLARE installment_fee DECIMAL(10,2);
  DECLARE first_date DATE;
  DECLARE remaining_days INT;
  DECLARE interval_days INT;

  -- Run only if fee or installments changed
  IF NOT (
       OLD.no_of_installments <=> NEW.no_of_installments
   AND OLD.fee_paid <=> NEW.fee_paid
  ) THEN

    IF NEW.no_of_installments IS NOT NULL
       AND NEW.fee_paid IS NOT NULL
       AND NEW.fee_paid > 0 THEN

      SET new_n = CAST(NEW.no_of_installments AS UNSIGNED);
      SET old_n = IF(OLD.no_of_installments IS NULL, 0, CAST(OLD.no_of_installments AS UNSIGNED));

      -- Calculate per-installment amount
      SET installment_fee = ROUND(NEW.fee_paid / new_n, 2);

      -- First installment = 1 week after placement date
      SET first_date = DATE_ADD(NEW.placement_date, INTERVAL 7 DAY);

      -- Remaining window: 2 months (~60 days) minus first week
      SET remaining_days = 53;

      IF new_n > 1 THEN
        SET interval_days = FLOOR(remaining_days / (new_n - 1));
      ELSE
        SET interval_days = 0;
      END IF;

      SET i = 1;
      WHILE i <= new_n DO

        -- INSERT if installment row does not exist
        IF NOT EXISTS (
          SELECT 1
          FROM placement_fee_collection
          WHERE placement_id = NEW.id
            AND installment_id = i
        ) THEN

          INSERT INTO placement_fee_collection (
            placement_id,
            installment_id,
            deposit_date,
            deposit_amount,
            amount_collected,
            lastmod_user_id
          )
          VALUES (
            NEW.id,
            i,
            DATE_ADD(first_date, INTERVAL (i - 1) * interval_days DAY),
            installment_fee,
            'no',
            NULL
          );

        ELSE
          -- UPDATE existing row ONLY if empty and not collected
          UPDATE placement_fee_collection
          SET
            deposit_date = DATE_ADD(first_date, INTERVAL (i - 1) * interval_days DAY),
            deposit_amount = installment_fee
          WHERE placement_id = NEW.id
            AND installment_id = i
            AND amount_collected = 'no'
            AND deposit_date IS NULL
            AND deposit_amount IS NULL;
        END IF;

        SET i = i + 1;
      END WHILE;
    END IF;

    -- SAFE DELETE: remove extra installments only if empty
    SET new_n = IF(NEW.no_of_installments IS NULL, 0, CAST(NEW.no_of_installments AS UNSIGNED));
    SET old_n = IF(OLD.no_of_installments IS NULL, 0, CAST(OLD.no_of_installments AS UNSIGNED));

    IF new_n < old_n THEN
      DELETE FROM placement_fee_collection
      WHERE placement_id = NEW.id
        AND installment_id > new_n
        AND amount_collected = 'no'
        AND deposit_amount IS NULL;
    END IF;

  END IF;
END */;;
DELIMITER ;
