--

DROP TABLE IF EXISTS `candidate_preparation`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `candidate_preparation` (
  `id` int NOT NULL AUTO_INCREMENT,
  `candidate_id` int NOT NULL,
  `start_date` date NOT NULL DEFAULT (curdate()),
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `instructor1_id` int DEFAULT NULL,
  `instructor2_id` int DEFAULT NULL,
  `instructor3_id` int DEFAULT NULL,
  `rating` enum('excellent','very good','good','average','need to improve') DEFAULT NULL,
  `communication` enum('excellent','very good','good','average','need to improve') DEFAULT NULL,
  `years_of_experience` int DEFAULT NULL,
  `target_date` date DEFAULT NULL,
  `notes` text,
  `linkedin_id` varchar(255) DEFAULT NULL,
  `github_url` varchar(255) DEFAULT NULL,
  `resume_url` varchar(255) DEFAULT NULL,
  `last_mod_datetime` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `move_to_mrkt` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `fk_instructor1` (`instructor1_id`),
  KEY `fk_instructor2` (`instructor2_id`),
  KEY `fk_instructor3` (`instructor3_id`),
  CONSTRAINT `fk_instructor1` FOREIGN KEY (`instructor1_id`) REFERENCES `employee` (`id`),
  CONSTRAINT `fk_instructor2` FOREIGN KEY (`instructor2_id`) REFERENCES `employee` (`id`),
  CONSTRAINT `fk_instructor3` FOREIGN KEY (`instructor3_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=277 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Candidate preparation status tracking';
/*!40101 SET character_set_client = @saved_cs_client */;

