CREATE TABLE `job_automation_keywords` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `category` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'blocked_personal_domain, allowed_staffing_domain, etc.',
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'email_extractor' COMMENT 'Which extractor uses this',
  `keywords` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Comma-separated: gmail.com,yahoo.com,outlook.com',
  `match_type` enum('exact','contains','regex') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'contains' COMMENT 'How to match',
  `action` enum('allow','block') COLLATE utf8mb4_unicode_ci DEFAULT 'block' COMMENT 'allow or block',
  `priority` int DEFAULT '100' COMMENT 'Lower = higher priority. Allowlist=1, Blocklist=100',
  `context` text COLLATE utf8mb4_unicode_ci COMMENT 'Why this filter exists',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_active` (`is_active`),
  KEY `idx_priority` (`priority`)
) ENGINE=InnoDB AUTO_INCREMENT=29 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
