  KEY `fk_job_types_job_owner_3` (`job_owner_3`),
  CONSTRAINT `fk_job_types_job_owner` FOREIGN KEY (`job_owner`) REFERENCES `employee` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_types_job_owner_1` FOREIGN KEY (`job_owner_1`) REFERENCES `employee` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_types_job_owner_2` FOREIGN KEY (`job_owner_2`) REFERENCES `employee` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_types_job_owner_3` FOREIGN KEY (`job_owner_3`) REFERENCES `employee` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_job_types_lastmod_user` FOREIGN KEY (`lastmod_user_id`) REFERENCES `employee` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
