--
-- Table structure for table `lead`
--

DROP TABLE IF EXISTS `lead`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lead` (
  `id` int NOT NULL AUTO_INCREMENT,
  `full_name` varchar(100) DEFAULT NULL,
  `entry_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `phone` varchar(45) DEFAULT NULL,
  `email` varchar(45) NOT NULL,
  `workstatus` varchar(50) DEFAULT NULL,
  `status` varchar(45) NOT NULL,
  `secondary_email` varchar(100) DEFAULT NULL,
  `secondary_phone` varchar(45) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `closed_date` date DEFAULT NULL,
  `notes` text,
  `last_modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `massemail_unsubscribe` tinyint(1) DEFAULT NULL,
  `massemail_email_sent` tinyint(1) DEFAULT NULL,
  `moved_to_candidate` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=11890 DEFAULT CHARSET=utf8mb3 COMMENT='Lead Management';
/*!40101 SET character_set_client = @saved_cs_client */;

