/*!50003 CREATE*/ /*!50017 DEFINER=`whitebox-db`@`%`*/ /*!50003 TRIGGER `after_lead_update_moved_to_candidate` AFTER UPDATE ON `lead` FOR EACH ROW BEGIN
    DECLARE latest_batch_id INT;

    -- Run only when moved_to_candidate changes from 0 → 1
    IF NEW.moved_to_candidate = 1 AND OLD.moved_to_candidate = 0 THEN

        -- Prevent inserting duplicate candidate based on phone
        IF NOT EXISTS (SELECT 1 FROM candidate WHERE phone = NEW.phone) THEN

            -- Get latest batch id
            SELECT batchid INTO latest_batch_id
            FROM batch
            ORDER BY batchid DESC
            LIMIT 1;

            -- Insert candidate
            INSERT INTO candidate (
                full_name,
                
                email,
                phone,
                status,
                workstatus,
                secondaryemail,
                secondaryphone,
                address,
                notes,
                batchid
            ) VALUES (
                NEW.full_name,
                NEW.email,
                NEW.phone,
                'active',
                NEW.workstatus,
                NEW.secondary_email,
                NEW.secondary_phone,
                NEW.address,
                NEW.notes,
                latest_batch_id
            );

        END IF;

    END IF;

END */;;
