  CONSTRAINT `fk_recording_id` FOREIGN KEY (`recording_id`) REFERENCES `recording` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
