/*!50003 CREATE*/ /*!50017 DEFINER=`whitebox-db`@`%`*/ /*!50003 TRIGGER `move_to_vendor_after_update` AFTER UPDATE ON `vendor_contact_extracts` FOR EACH ROW BEGIN
    IF NEW.moved_to_vendor = 1 AND OLD.moved_to_vendor = 0 THEN
        INSERT INTO vendor (
            full_name,
            phone_number,
            email,
            linkedin_id,
            company_name,
            location,
            created_at,
            linkedin_internal_id
        )
        VALUES (
            NEW.full_name,
            NEW.phone,
            NEW.email,
            NEW.linkedin_id,
            NEW.company_name,
            NEW.location,
            NOW(),
            NEW.linkedin_internal_id
        );
    END IF;
END */;;
